test-case.test:
(: ForScoreExpr-5: Basic syntax: two for clauses :)
declare variable $input-context external;
for $m score $s1 in $input-context//metadata[title contains text "Usability"], 
    $p score $s2 in $m//subject[. contains text "Web site"]
return ($m/title,$p)

(: ForScoreExpr-Var2: Score variable returned properly :)
declare variable $input-context external;
for $t score $s in $input-context//metadata[title contains text "Usability"]
return ($s ge 0.0) and ($s le 1.0)

(: ForScoreExpr-Var3: Score variable shadows global :)
declare variable $input-context external;
declare variable $s := 47;
for $t score $s in $input-context//metadata[title contains text "Usability"]
return ($s ge 0.0) and ($s le 1.0)

(: LetScoreExpr-1: Basic syntax: score variable :)
declare variable $input-context external;
let score $s := $input-context//metadata/title[. contains text "Usability"]
return ($s ge 0.0) and ($s le 1.0)
